const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let idx = 0;

const M = data[idx++];
const N = data[idx++];

const stock = Array.from({ length: M + 1 }, () => Array(N + 1).fill(0));

for (let i = 1; i <= M; i++) {
    for (let j = 1; j <= N; j++) {
        stock[i][j] = data[idx++];
    }
}

const P = data[idx++];
let sold = 0;

for (let k = 0; k < P; k++) {
    const I = data[idx++];
    const J = data[idx++];

    if (stock[I][J] > 0) {
        stock[I][J]--;
        sold++;
    }
}

console.log(sold);
